use crate::*;
pub const ENERGY_SOURCE:&str="https://basc.pnnl.gov/information/2009-2021-iecc-and-irc-minimum-insulation-requirements-new-homes";
pub fn counties()->&'static Value{static D:OnceLock<Value>=OnceLock::new();D.get_or_init(||serde_json::from_str(include_str!("../data/counties.json")).unwrap())}
pub fn locate(lat:f64,lon:f64)->Option<Value>{counties().as_array()?.iter().find(|c|{let b=c["bbox"].as_array().unwrap();if lon<b[0].as_f64().unwrap()||lat<b[1].as_f64().unwrap()||lon>b[2].as_f64().unwrap()||lat>b[3].as_f64().unwrap(){return false}let mut inside=false;for ring in c["rings"].as_array().unwrap(){let ps=ring.as_array().unwrap();let mut j=ps.len()-1;for i in 0..ps.len(){let(xi,yi,xj,yj)=(ps[i][0].as_f64().unwrap(),ps[i][1].as_f64().unwrap(),ps[j][0].as_f64().unwrap(),ps[j][1].as_f64().unwrap());if (yi>lat)!=(yj>lat)&&lon<(xj-xi)*(lat-yi)/(yj-yi)+xi{inside=!inside}j=i;}}inside}).map(|c|json!({"id":c["id"],"name":c["name"],"state":c["state"],"zone":c["zone"],"oldZone":c["oldZone"]}))}
pub fn profile(c:&Config)->Value{let county=counties().as_array().unwrap().iter().find(|x|s(x,"id")==c.county);let old=c.energy_code=="2018 IECC";let zone=county.map(|x|s(x,if old{"oldZone"}else{"zone"})).unwrap_or("4A");let z=zone.chars().next().and_then(|x|x.to_digit(10)).unwrap_or(4);let ceiling=if old{if z==1{30}else if z<=3{38}else{49}}else if z==1{30}else if z<=3{49}else{60};let ci=if (old&&z>=6)||(!old&&z>=4){6}else{0};let face="Kraft faced";let slab=if (!old&&z>=3)||(old&&z>=4){10}else{0};let dep=if slab==0{0}else if (!old&&z>=4)||(old&&z>=6){4}else{2};json!({"zone":zone,"located":county.is_some(),"countyName":county.map(|x|s(x,"name")).unwrap_or("No location selected"),"state":county.map(|x|s(x,"state")).unwrap_or(""),"wallR":21,"continuousR":0,"requiredContinuousR":ci,"requiredAtticR":ceiling,"atticR":49,"facing":face,"slabR":slab,"slabDepth":dep,"source":ENERGY_SOURCE,"status":if c.code_confirmed&&!c.jurisdiction.is_empty(){"User-confirmed model-code basis; local amendments pending"}else{"Model-code estimate; local adoption unverified"},"notes":["ZIP locates an approximate postal center, not a permitting jurisdiction. Confirm the county and adopted editions with the building department.","R-21 fiberglass fills the 2 × 6 wall cavity. The specified 7/16 ZIP / R-21 panel is retained; any extra insulation required by the selected code path is an unresolved assembly review.","ZIP sheathing replaces exterior housewrap. It does not replace under-slab vapor control or any required interior vapor retarder. Separate vapor membranes are excluded at your request and remain a compliance hold.","Snow, wind, seismic, frost depth, soil, setbacks, egress, electrical circuits, plumbing and HVAC require site-specific design; they are not certified by this estimate."]})}
pub fn electrical(rs:&[Room],ws:&[Wall],f:&[staging::Furniture],c:&Config)->Value{let mut schedule=vec![];for r in rs{let mut total=0;for wall in ws{let along=wall.axis=="x";let line=if along{wall.z}else{wall.x};let a=if along{r.z}else{r.x};let b=a+if along{r.d}else{r.w};if !near(line,a)&&!near(line,b){continue}let start=if along{wall.x}else{wall.z};let lo=start.max(if along{r.x}else{r.z});let hi=(start+wall.length).min(if along{r.x+r.w}else{r.z+r.d});if hi<=lo{continue}let mut cursor=lo;let mut ops=wall.openings.iter().filter(|o|o.kind!="window"||o.bottom<0.5).collect::<Vec<_>>();ops.sort_by(|a,b|a.at.total_cmp(&b.at));for o in ops{let end=(start+o.at).min(hi);let len=end-cursor;if len>=2.{total+=(len/12.).ceil() as usize;}cursor=cursor.max(start+o.at+o.width);}let len=hi-cursor;if len>=2.{total+=(len/12.).ceil() as usize;}}
let count=match r.kind.as_str(){"bath"=>1,"hall"=>usize::from(r.w.max(r.d)>=10.),"kitchen"=>{let run:f64=f.iter().filter(|x|x.room_id==r.id&&(x.kind=="kitchen"||x.kind=="counter-run")).map(|x|x.local_width).sum();(run/4.).ceil().max(2.) as usize},_=>total};let island=if c.electrical_code=="2020 NEC"&&f.iter().any(|x|x.room_id==r.id&&x.kind=="island"){2}else{0};let laundry=usize::from(r.name.to_lowercase().contains("laundry"));schedule.push(json!({"room":r.name,"count":count+island+laundry,"basis":match r.kind.as_str(){"bath"=>"One basin receptacle allowance; GFCI required","kitchen"=>"Modeled counter run at 4 ft coverage; appliances/circuits separate","hall"=>"One where modeled hallway is at least 10 ft",_=>"Each modeled wall segment ≥ 2 ft; maximum 12 ft coverage; conservative corner rounding"}}));}
let exterior=if c.active_floor==0{2}else{0};let total=schedule.iter().map(|x|n(x,"count") as usize).sum::<usize>()+exterior;json!({"total":total,"interior":total-exterior,"exterior":exterior,"schedule":schedule,"edition":c.electrical_code,"status":"Layout allowance, not an approved electrical plan","note":"Counts follow modeled wall segments and counter lengths. AFCI/GFCI, circuit loads, appliance outlets, islands, local amendments and exact outlet locations require electrical design. 2023 island provision is a future-wiring allowance."})}

pub const OPENING_SOURCE:&str="https://codes.iccsafe.org/content/IRC2021P1/chapter-3-building-planning";
pub fn adjacent_rooms<'a>(o:&Opening,w:&Wall,rs:&'a [Room])->Vec<&'a Room>{
 let along=w.axis=="x";let mid=if along{w.x+o.at+o.width/2.}else{w.z+o.at+o.width/2.};
 rs.iter().filter(|r|{let lo=if along{r.x}else{r.z};let hi=lo+if along{r.w}else{r.d};let line=if along{w.z}else{w.x};let front=if along{r.z}else{r.x};let back=front+if along{r.d}else{r.w};mid>=lo&&mid<=hi&&(near(line,front)||near(line,back)||(line>front&&line<back))}).collect()
}
pub fn opening_error(os:&[Opening],w:&Wall,c:&Config,rs:&[Room])->Option<String>{
 for o in os{if let Some(error)=garage::connection_error(o,w,c,rs){return Some(error)}}
 for o in os.iter().filter(|o|o.kind=="window"){
  if adjacent_rooms(o,w,rs).iter().any(|r|r.kind=="bedroom")&&w.exterior{
   if o.bottom>3.5+1e-8{return Some("Bedroom window rough sills cannot exceed 42 in in this model, reserving 2 in for the selected window frame below the 44 in clear-sill limit.".into())}
   if o.width<3.-1e-8||o.height<4.-1e-8{return Some("Use at least a 36 x 48 in rough opening for the bedroom window. Its selected product must separately provide the required net clear escape opening.".into())}
  }
 }
 if !model::valid_openings(os,w.length,c.wall_height){return Some("Opening dimensions overlap, exceed the wall/header limits, or fall outside the height guardrails. Doors need a zero sill and at least 82.5 in rough height; window rough sills start at 24 in.".into())}
 None
}
pub fn opening_schedule(c:&Config,rs:&[Room],ws:&[Wall])->Value{
 let mut schedule=vec![];let mut issues=vec![];
 for w in ws{for o in &w.openings{let rooms=adjacent_rooms(o,w,rs);let bedroom=w.exterior&&rooms.iter().any(|r|r.kind=="bedroom");let error=opening_error(std::slice::from_ref(o),w,c,rs);if let Some(e)=&error{issues.push(format!("{}: {}",o.id,e));}
 schedule.push(json!({"id":o.id,"wallId":w.id,"kind":o.kind,"rooms":rooms.iter().map(|r|&r.name).collect::<Vec<_>>(),"bedroomEscapeCandidate":bedroom,"roughSillInches":round(o.bottom*12.),"roughHeightInches":round(o.height*12.),"roughWidthInches":round(o.width*12.),"heightGuardrailPass":error.is_none(),"requiredFinishedClearHeightInches":if o.kind=="door"{json!(78)}else{Value::Null},"maximumFinishedClearSillInches":if bedroom{json!(44)}else{Value::Null},"productStatus":if o.kind=="door"{"Confirm the selected door delivers at least 78 in finished clear height; required egress door also needs 32 in clear width."}else if bedroom{"Product must be operable and certify net clear height >=24 in, width >=20 in, area >=5.7 sq ft and clear sill <=44 in; rough dimensions do not prove net opening."}else{"Confirm product fit, safety glazing, operation and any site-dependent fall protection."},"basis":c.building_code}));
 }}
 for r in rs.iter().filter(|r|r.kind=="bedroom"){if !ws.iter().filter(|w|w.exterior).any(|w|w.openings.iter().any(|o|["window","door"].contains(&o.kind.as_str())&&adjacent_rooms(o,w,rs).iter().any(|a|a.id==r.id))){issues.push(format!("{} has no exterior escape candidate after wall edits. Provide a verified escape opening.",r.name));}}
 json!({"edition":c.building_code,"schedule":schedule,"issues":issues,"allHeightGuardrailsPass":schedule.iter().all(|o|o["heightGuardrailPass"]==true),"status":"Model height guardrails; product clear dimensions, finished floor datum and local approval still required","source":OPENING_SOURCE,"source2024":"https://townofseverance.org/DocumentCenter/View/209/2024-IRC-Window-Replacement-Guide-PDF","rules":{"minimumFinishedDoorClearHeightInches":78,"minimumFinishedEgressDoorClearWidthInches":32,"maximumBedroomWindowClearSillInches":44,"minimumEscapeWindowClearWidthInches":20,"minimumEscapeWindowClearHeightInches":24,"minimumEscapeWindowClearAreaSquareFeet":5.7}})
}

/// When a window is made wider than the space beside it allows, the windows it would run into make way: they are
/// removed (doors and passages never are). Returns the openings and how many windows went, if that makes it fit.
pub fn widen_window(os:&[Opening],id:&str,wall:&Wall,c:&Config,rooms:&[Room])->Option<(Vec<Opening>,usize)>{
 let me=os.iter().find(|o|o.id==id)?;if me.kind!="window"{return None}
 let(lo,hi)=(me.at-0.5,me.at+me.width+0.5);
 let kept:Vec<Opening>=os.iter().filter(|o|o.id==id||o.kind!="window"||o.at+o.width<=lo||o.at>=hi).cloned().collect();
 let gone=os.len()-kept.len();if gone==0{return None}
 opening_error(&kept,wall,c,rooms).is_none().then_some((kept,gone))
}
